use ingetrazo_gui::IngeTrazoApp;
use ingetrazo_core::georef::{SceneDatum,GeoPath};
fn main(){let path=std::path::PathBuf::from(std::env::args().nth(1).unwrap());let mut result=vec![];for seeded in [false,true]{let mut a=IngeTrazoApp::new();a.scene.mesh.add_vertex(glam::DVec3::new(9.,8.,7.));a.scene.geo_paths.push(GeoPath::new(vec![glam::DVec3::new(4.,5.,6.),glam::DVec3::new(7.,8.,9.)],false,"Existing"));if seeded{a.scene.geo_datum=Some(SceneDatum::new(-13.5,-71.9,1234.,23.))}a.import_geographic_paths(&path).unwrap();let mut states=vec![];for phase in ["import","undo","redo"]{if phase=="undo"{a.undo()}if phase=="redo"{a.redo()}let d=a.scene.geo_datum.as_ref().unwrap();states.push(serde_json::json!({"phase":phase,"datum":[d.lat,d.lon,d.alt,d.north],"paths":a.scene.geo_paths.iter().map(|p|serde_json::json!({"name":p.name,"closed":p.closed,"points":p.points.iter().map(|p|p.to_array()).collect::<Vec<_>>()})).collect::<Vec<_>>(),"vertices":a.scene.mesh.vertices.len()}));}result.push(states)}println!("{}",serde_json::to_string(&result).unwrap())}
